import java.util.Scanner;

public class Main {

    public void solve() {
        Scanner input = new Scanner(System.in);
        long base = input.nextLong();
        long target = input.nextLong();
        int powerCount = 0;
        while (Math.pow(base, powerCount) < target) {
            powerCount++;
        }
        if (Math.pow(base, powerCount) == target) {
            System.out.println("YES");
            return;
        }

        long maxPowerVal = (long) Math.pow(base, powerCount);
        long sumOfSeries = (maxPowerVal - 1) / (base - 1);
        if (maxPowerVal - sumOfSeries == target) {
            System.out.println("YES");
            return;
        }
        if (recursiveCheckDivisibility(base, target)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }

    private boolean recursiveCheckDivisibility(long base, long target) {
        if (target == 1) {
            return true;
        }
        if (target % base == 0) {
            return recursiveCheckDivisibility(base, target / base);
        } else if ((target - 1) % base == 0) {
            return recursiveCheckDivisibility(base, (target - 1) / base);
        } else if ((target + 1) % base == 0) {
            return recursiveCheckDivisibility(base, (target + 1) / base);
        }
        return false;
    }

    public static void main(String[] args) {
        new Main().solve();
    }
}
